use super::*;
#[component]
pub fn SettingsView(ui: Ui) -> impl IntoView {
    view! {<div class="settings-page"><div class="page-heading"><h1>"Settings"</h1></div><div class="tabs" role="tablist" aria-label="Settings sections">{["appearance","integrations","application"].into_iter().map(|tab|view!{<button role="tab" aria-selected=move||(ui.settings_tab.get()==tab).to_string() class:active=move||ui.settings_tab.get()==tab on:click=move|_|ui.settings_tab.set(tab.into())>{match tab{"appearance"=>"Appearance","integrations"=>"Integrations",_=>"Application"}}</button>}).collect_view()}</div>
    {move||match ui.settings_tab.get().as_str(){"appearance"=>view!{<Appearance ui/>}.into_any(),"integrations"=>view!{<Integrations ui/>}.into_any(),_=>view!{<section class="settings-section"><h2>"Application"</h2><label class="setting-row"><span><strong>"Automatically select music videos"</strong><small>"Prefer the music-video version when one is available."</small></span><input type="checkbox" prop:checked=move||ui.settings.with(|s|s.auto_video) on:change=move|e|{ui.settings.update(|s|s.auto_video=event_target_checked(&e));ui.save_plugins();}/></label><label class="setting-row"><span><strong>"Keep playing when the window closes"</strong><small>"Find lazytune in your system tray. Quit always stops playback."</small></span><input type="checkbox" prop:checked=move||ui.settings.with(|s|s.close_to_tray) on:change=move|e|{ui.settings.update(|s|s.close_to_tray=event_target_checked(&e));ui.save_plugins();}/></label><div class="setting-row"><span><strong>"YouTube Music account"</strong><small>"Your session stays in this app’s webview profile."</small></span><div class="actions"><button class="secondary" on:click=move|_|ui.show_player("login")>"Open account"</button><button class="secondary" on:click=move|_|spawn_local(async move{match call::<()>("logout",json!({})).await{Ok(())=>{ui.page.set(CatalogPage::default());ui.home_library.set(CatalogPage::default());ui.notice.set("YouTube Music session cleared".into());},Err(e)=>ui.notice.set(e)}})>"Sign out"</button></div></div><p class="muted">{concat!("lazytune ", env!("CARGO_PKG_VERSION"))}</p></section>}.into_any()}}
    </div>}
}
#[component]
fn Appearance(ui: Ui) -> impl IntoView {
    let theme_action = move |name: &'static str| {
        spawn_local(async move {
            match call::<Option<ThemePack>>(name, json!({})).await {
                Ok(Some(t)) => ui.preview.set(Some(t)),
                Ok(None) => {}
                Err(e) => ui.notice.set(e),
            }
        })
    };
    view! {<section class="settings-section"><div class="section-heading"><div><h2>"Appearance"</h2><p>"Colors, background, and layout."</p></div><button class="secondary" on:click=move|_|theme_action("import_theme")>"Import theme"</button></div>
    <div class="theme-banner"><div><h3>{move||ui.settings.with(|s|s.theme.name.clone())}</h3></div><button class="secondary" on:click=move|_|spawn_local(async move{ui.message(call::<()>("export_theme",json!({})).await);})>"Export theme"</button></div>
    <label class="field-label">"Theme name"<input prop:value=move||ui.draft.get().name maxlength="80" on:input=move|e|ui.draft.update(|t|t.name=event_target_value(&e))/></label>
    <div class="palette-editor">{["background","surface","text","muted","accent"].into_iter().map(|key|view!{<label><input type="color" aria-label=key prop:value=move||{let p=ui.draft.get().palette;match key{"background"=>p.background,"surface"=>p.surface,"text"=>p.text,"muted"=>p.muted,_=>p.accent}} on:input=move|e|ui.draft.update(|t|{let p=&mut t.palette;let value=event_target_value(&e);match key{"background"=>p.background=value,"surface"=>p.surface=value,"text"=>p.text=value,"muted"=>p.muted=value,_=>p.accent=value}})/><span>{key}</span></label>}).collect_view()}</div>
    <div class="setting-row"><span><strong>"Background image"</strong><small>"PNG or JPEG, up to 10 MiB."</small></span><div class="actions"><button class="secondary" on:click=move|_|theme_action("choose_wallpaper")>"Choose wallpaper"</button><button class="text-button" on:click=move|_|ui.draft.update(|t|t.wallpaper=None)>"Remove"</button></div></div>
    <label class="setting-row"><span><strong>"Colors from artwork"</strong><small>"Blend cover colors into the app background."</small></span><input type="checkbox" prop:checked=move||ui.draft.with(|t|t.song_colors) on:change=move|e|ui.draft.update(|t|t.song_colors=event_target_checked(&e))/></label><label class="setting-row"><span><strong>"Use album artwork as background"</strong><small>"Use the current album art behind your player when no wallpaper is selected."</small></span><input type="checkbox" prop:checked=move||ui.draft.get().artwork_colors on:change=move|e|ui.draft.update(|t|t.artwork_colors=event_target_checked(&e))/></label>
    <label class="setting-row"><span><strong>"Glassy playback bar"</strong><small>"Use a translucent background for playback controls."</small></span><input type="checkbox" prop:checked=move||ui.draft.with(|t|t.glassy_player) on:change=move|e|ui.draft.update(|t|t.glassy_player=event_target_checked(&e))/></label>
    <label class="setting-row"><span><strong>"Audio visualizer"</strong><small>"Respond to the music behind your background and controls."</small></span><select aria-label="Audio visualizer" prop:value=move||match ui.draft.with(|t|t.visualizer){VisualizerMode::Off=>"off",VisualizerMode::BackgroundPulse=>"background_pulse",VisualizerMode::SpectrumBars=>"spectrum_bars"} on:change=move|e|ui.draft.update(|t|t.visualizer=match event_target_value(&e).as_str(){"background_pulse"=>VisualizerMode::BackgroundPulse,"spectrum_bars"=>VisualizerMode::SpectrumBars,_=>VisualizerMode::Off})><option value="off">"Off"</option><option value="background_pulse">"Background pulse"</option><option value="spectrum_bars">"Spectrum bars"</option></select></label>
    <label class="setting-row"><span><strong>"Background dimming"</strong></span><input type="range" min="0" max="1" step="0.01" prop:value=move||ui.draft.get().dim.to_string() on:input=move|e|{if let Ok(n)=event_target_value(&e).parse(){ui.draft.update(|t|t.dim=n);}}/></label>
    <label class="setting-row"><span><strong>"Background blur"</strong></span><input type="range" min="0" max="40" step="1" prop:value=move||ui.draft.get().blur.to_string() on:input=move|e|{if let Ok(n)=event_target_value(&e).parse(){ui.draft.update(|t|t.blur=n);}}/></label>
    <label class="setting-row"><span><strong>"Layout density"</strong></span><select prop:value=move||if ui.draft.get().density==Density::Compact{"compact"}else{"comfortable"} on:change=move|e|ui.draft.update(|t|t.density=if event_target_value(&e)=="compact"{Density::Compact}else{Density::Comfortable})><option value="comfortable">"Comfortable"</option><option value="compact">"Compact"</option></select></label>
    <h2 class="subheading">"Player layout"</h2><p>"Move player blocks between the main area and the side panel. Navigation and playback controls always stay available."</p>
    {[Block::Artwork,Block::Queue,Block::Lyrics,Block::Details].into_iter().map(|block|view!{<div class="setting-row"><strong>{block.label()}</strong><div class="actions"><button class="text-button" on:click=move|_|ui.draft.update(|t|{for region in [&mut t.layout.main,&mut t.layout.side]{if let Some(i)=region.iter().position(|b|*b==block){if i>0{region.swap(i,i-1);}}}})>"Move up"</button><select aria-label=format!("{} location",block.label()) prop:value=move||{let t=ui.draft.get();if t.layout.main.contains(&block){"main"}else if t.layout.side.contains(&block){"side"}else{"hidden"}} on:change=move|e|ui.draft.update(|t|{t.layout.main.retain(|b|*b!=block);t.layout.side.retain(|b|*b!=block);match event_target_value(&e).as_str(){"main"=>t.layout.main.push(block),"side"=>t.layout.side.push(block),_=>{}}})><option value="main">"Main area"</option><option value="side">"Side panel"</option><option value="hidden">"Hidden"</option></select></div></div>}).collect_view()}
    <h2 class="subheading">"Discover"</h2>{["recommendations","library"].into_iter().map(|key|view!{<label class="setting-row"><span>{if key=="library"{"Your library"}else{"Recommendations"}}</span><input type="checkbox" prop:checked=move||ui.draft.get().layout.home.contains(&key.to_string()) on:change=move|e|ui.draft.update(|t|{t.layout.home.retain(|x|x!=key);if event_target_checked(&e){t.layout.home.push(key.into());}})/></label>}).collect_view()}
    <div class="actions settings-save"><Show when=move||!ui.appearance_error.get().is_empty()><p class="error" role="alert">{move||ui.appearance_error.get()}</p></Show><button class="text-button" on:click=move|_|spawn_local(async move{match call::<ThemePack>("reset_theme",json!({})).await{Ok(t)=>{ui.settings.update(|s|s.theme=t.clone());ui.draft.set(t);},Err(e)=>ui.notice.set(e)}})>"Reset to default"</button></div></section>}
}
#[component]
fn Integrations(ui: Ui) -> impl IntoView {
    let token = RwSignal::new(String::new());
    view! {<section class="settings-section"><h2>"Integrations"</h2><p>"Enable the features you use."</p>
    {[("discord","Discord Rich Presence","Share what you’re listening to with your Discord friends."),("adblock","Ad blocking","Filter YouTube Music ads with the built-in player adapter."),("sponsorblock","SponsorBlock","Skip sponsored and non-music sections using community segments."),("lyrics","Synchronized lyrics","Follow every line, with lyrics supplied by LRCLIB."),("lastfm","Last.fm","Keep a record of the music you actually listen to."),("listenbrainz","ListenBrainz","Add your listening history to your ListenBrainz profile.")].into_iter().map(|(id,title,description)|view!{<label class="setting-row integration"><span><strong>{title}</strong><small>{description}</small><span class="plugin-status">{move||ui.statuses.get().iter().find(|s|s.id==id).map(|s|format!("{} · {}",s.state,s.detail)).unwrap_or_else(||"Off".into())}</span></span><input type="checkbox" prop:checked=move||{let p=ui.settings.with(|s|s.plugins.clone());match id{"discord"=>p.discord,"adblock"=>p.adblock,"sponsorblock"=>p.sponsorblock,"lyrics"=>p.lyrics,"lastfm"=>p.lastfm,_=>p.listenbrainz}} on:change=move|e|{let checked=event_target_checked(&e);ui.settings.update(|s|match id{"discord"=>s.plugins.discord=checked,"adblock"=>s.plugins.adblock=checked,"sponsorblock"=>s.plugins.sponsorblock=checked,"lyrics"=>s.plugins.lyrics=checked,"lastfm"=>s.plugins.lastfm=checked,_=>s.plugins.listenbrainz=checked});ui.save_plugins();}/></label>}).collect_view()}
    <h2 class="subheading">"Connect your accounts"</h2><div class="setting-row"><span><strong>"Last.fm"</strong><small>"Authorize lazytune in your browser, then finish connecting here."</small></span><div class="actions"><button class="secondary" on:click=move|_|spawn_local(async move{match call::<String>("lastfm_connect",json!({})).await{Ok(t)=>ui.lastfm_token.set(t),Err(e)=>ui.notice.set(e)}})>"Authorize"</button><button class="primary" disabled=move||ui.lastfm_token.get().is_empty() on:click=move|_|spawn_local(async move{match call::<()>("lastfm_finish",json!({"token":ui.lastfm_token.get_untracked()})).await{Ok(())=>{ui.lastfm_token.set(String::new());ui.notice.set("Last.fm connected".into());},Err(e)=>ui.notice.set(e)}})>"Finish connection"</button></div></div>
    <label class="field-label">"ListenBrainz user token"<input type="password" autocomplete="off" placeholder="Paste your token from ListenBrainz settings" prop:value=move||token.get() on:input=move|e|token.set(event_target_value(&e))/></label><button class="secondary" on:click=move|_|spawn_local(async move{match call::<()>("set_credential",json!({"service":"listenbrainz","value":token.get_untracked()})).await{Ok(())=>{token.set(String::new());ui.notice.set("ListenBrainz credential updated".into());},Err(e)=>ui.notice.set(e)}})>"Save token"</button>
    <h2 class="subheading">"Options"</h2><label class="setting-row"><span><strong>"Lyrics timing offset"</strong><small>"Seconds, from −30 to +30."</small></span><input type="number" min="-30" max="30" step="0.1" prop:value=move||ui.settings.with(|s|s.plugins.clone()).lyrics_offset.to_string() on:change=move|e|{if let Ok(n)=event_target_value(&e).parse(){ui.settings.update(|s|s.plugins.lyrics_offset=n);ui.save_plugins();}}/></label>
    <fieldset class="segment-options"><legend>"SponsorBlock categories"</legend>{["sponsor","music_offtopic","intro","outro","selfpromo","interaction","preview"].into_iter().map(|category|view!{<label><input type="checkbox" prop:checked=move||ui.settings.with(|s|s.plugins.clone()).sponsor_categories.contains(&category.to_string()) on:change=move|e|{let checked=event_target_checked(&e);ui.settings.update(|s|{s.plugins.sponsor_categories.retain(|v|v!=category);if checked{s.plugins.sponsor_categories.push(category.into());}});ui.save_plugins();}/>{category.replace('_'," ")}</label>}).collect_view()}</fieldset>
    </section>}
}
